"""Создаёт собственные учебные примеры и PDF. Нужен reportlab и DejaVu Sans."""
from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer
from reportlab.lib.styles import ParagraphStyle
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.enums import TA_LEFT

ROOT = Path(__file__).resolve().parents[2] / 'docs/demo'
ROOT.mkdir(parents=True, exist_ok=True)
short = '''Алгоритм - это конечная последовательность понятных исполнителю шагов для решения задачи. Один и тот же результат можно получить разными алгоритмами, но время и расход памяти могут отличаться. Линейный поиск просматривает элементы последовательно и работает даже в неотсортированном массиве. В худшем случае он проверяет все n элементов. Бинарный поиск требует отсортированного массива и после каждого сравнения отбрасывает половину оставшегося диапазона. Число шагов растёт пропорционально логарифму n. Перед выбором алгоритма нужно проверить его условия применимости, а не только скорость. Для маленького массива простой линейный поиск иногда удобнее, несмотря на более высокую асимптотическую оценку.'''
second = '''Модульный тест проверяет небольшую часть программы отдельно от внешних систем. Заглушка заменяет зависимость предсказуемым поведением: например, вместо вызова языковой модели возвращает заранее заданный ответ. Интеграционный тест проверяет совместную работу нескольких компонентов. HTTP-тест отправляет настоящий запрос локальному серверу и проверяет код ответа, заголовки и тело. Положительный сценарий показывает, что корректный запрос работает. Отрицательный сценарий проверяет понятную ошибку при неверных данных. Тесты должны быть воспроизводимыми: обычный запуск не должен зависеть от доступности внешнего API или секретного ключа. Проверка через curl дополняет автоматические тесты, но не заменяет их.'''
(ROOT/'short-text.txt').write_text(short+'\n')
(ROOT/'short-file.txt').write_text(second+'\n')
heads = [
('Данные и инварианты', 'Инвариант - условие, которое программа сохраняет до и после операции. В списке заказов идентификаторы должны быть уникальными, а количество не может быть отрицательным. Проверка инварианта относится к границе изменения данных. Если условие нарушено, операция должна завершиться ошибкой без частичного изменения состояния. Пустая коллекция является нормальным входом, если контракт явно не запрещает её. Размер входа нужно ограничивать до дорогих вычислений.'),
('Поиск и сложность', 'Линейный поиск последовательно сравнивает элементы с образцом. Для n элементов худший случай требует n сравнений. Бинарный поиск делит отсортированный диапазон пополам. Сортировка является обязательным условием: без неё корректность результата не гарантируется. Оценка O(n) описывает рост затрат при увеличении входа, а не точное время в миллисекундах. Измерения на конкретном компьютере дополняют асимптотический анализ.'),
('Очереди и фоновые задания', 'Очередь хранит задания в порядке поступления. Один исполнитель начинает следующее задание после завершения предыдущего. Клиент получает идентификатор задания и отдельно проверяет статус. Состояния в очереди, выполняется, готово и ошибка имеют разные значения. Прогресс отражает завершённые части, а не приблизительное обещание времени. При ошибке части нельзя выдавать неполный ответ как итоговый. Временное хранение требует срока удаления.'),
('Протокол HTTP и ошибки', 'Метод GET читает состояние ресурса. POST создаёт ресурс или запускает действие. Ответ 202 означает принятие задания, но не готовность результата. Клиент опрашивает адрес из Location с рекомендованным интервалом. Ошибка 400 относится к неверному запросу, 413 к превышению допустимого размера, а 404 к отсутствующему ресурсу. Сбой внешнего сервиса требует отдельного понятного сообщения. Повторный POST может создать второе задание.'),
('Тестирование и измерения', 'Тест должен иметь известные входные данные и проверяемое ожидание. Заглушка внешнего сервиса позволяет воспроизвести успех, отказ и задержку без ключа и интернета. Для очереди важно проверить порядок выполнения и обновление прогресса. При измерении времени учитывают ожидание очереди и внешних лимитов. Один успешный замер не доказывает одинаковую скорость на всех машинах. Нужно отдельно записывать условия эксперимента и ограничения выборки.'),
('Безопасность и ресурсы', 'Секретный ключ хранится только на сервере и не попадает в мобильное приложение, Git или журналы. Внешний ответ нельзя целиком копировать в сообщение об ошибке. Ограничение размера файла защищает память, а таймаут ограничивает длительность разбора. Файл с паролем нужно отклонить, а не пытаться обходить защиту. После завершения или ошибки временные файлы удаляются. Лимит количества заданий ограничивает накопление данных в памяти.')]
paragraphs=[]
for number,(title,intro) in enumerate(heads,1):
    sentences=[f'{number}. {title}. {intro}']
    # Разные разобранные задачи, а не персональные или заимствованные материалы.
    cases=[
        f'В учебном примере {number} команда принимает {number*12} запросов за минуту. Если ограничение составляет {number*10}, лишние {number*2} запроса нельзя незаметно потерять: сервер должен сообщить об отказе либо поставить их в ограниченную очередь.',
        f'Для набора из {number*20} элементов проверяется пустой вход, один элемент и полный набор. Если ошибка возникает на шаге {number+1}, тест проверяет отсутствие итогового результата и освобождение ресурсов. Сам факт вызова функции ещё не доказывает корректность данных.',
        f'Предположим, что обработка одной части занимает {number+2} секунды. Для четырёх последовательных частей чистое время составит {4*(number+2)} секунд. Ожидание квоты и объединение добавляются отдельно. Этот расчёт относится к условному примеру, а не к обещанию скорости сервиса.',
        f'На проверке примера {number} ревьюер сравнивает вход, контракт и наблюдаемый результат. Название режима должно совпадать в запросе и ответе. Числовые значения нельзя округлять так, чтобы менялся смысл условия. Если источник не содержит нужного определения, модель не должна дополнять его догадкой.',
        f'Упражнение для раздела {number}: объясните, какое условие необходимо проверить до начала работы. Затем назовите успешный исход и два разных отказа. Покажите, какие сведения нужны клиенту для повторной попытки. Не включайте в ошибку содержимое документа или секретные настройки.',
        f'При проверке раздела {number} полезно повторить эксперимент с теми же данными и явно отметить изменение настроек. Сравнение имеет смысл только при одинаковом размере материала. Пиковая память, число вызовов и длительность измеряются отдельно; ни одна из этих величин не заменяет оценку качества ответа.'
    ]
    cases.extend([
        f'Дополнительная проверка раздела {number} рассматривает граничные значения: допустимый максимум, значение на единицу меньше и значение на единицу больше. Принятый материал должен пройти полностью. Превышение лимита должно давать одинаковый код при повторе. Нельзя проверять только удобный средний пример и считать остальные входы автоматически корректными.',
        f'Если два клиента одновременно читают состояние примера {number}, они должны увидеть согласованные поля: число завершённых частей не превышает общее число частей, а успешное задание содержит итог. После перезапуска память очищается, поэтому клиенту может понадобиться повторная отправка. Это свойство выбранного временного хранения нужно объяснить заранее.',
        f'Завершая раздел {number}, отделим наблюдение от вывода. Успешный ответ сервера подтверждает выполнение конкретного запроса. Он не доказывает отсутствие ошибок на любых других документах. Для содержательной проверки нужно сверить определения и вычисления с исходным материалом, затем зафиксировать найденные ограничения и способ их воспроизведения.'
    ])
    sentences.extend(cases)
    para=' '.join(sentences)
    paragraphs.append(para)
(ROOT/'long-lecture.txt').write_text('\n\n'.join(paragraphs[:4])+'\n')

english=[]
for section in range(2):
    lines=[('Sequential processing and test design.' if section==0 else 'HTTP contracts and resource limits.')]
    for i in range(1,20):
        lines.append(f'Case {section*20+i}: a service accepts {i*3} tasks and processes them in arrival order. '
                     f'If each task takes {i+1} seconds, the work alone takes {i*3*(i+1)} seconds. '
                     'Queue waiting and provider quota delays must be measured separately. A test records the input, '
                     'checks completed work and verifies a clear failure instead of a partial success. '
                     'The example uses synthetic data and does not predict production speed.')
    english.append(' '.join(lines))
# Each paragraph fits an 8000-byte part; the complete text exceeds the synchronous character limit.
(ROOT/'benchmark-2-parts.txt').write_text('\n\n'.join(x[:7600] for x in english)+'\n')
pdfmetrics.registerFont(TTFont('DejaVu', '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'))
style=ParagraphStyle('body',fontName='DejaVu',fontSize=10.5,leading=15,spaceAfter=10,alignment=TA_LEFT)
title=ParagraphStyle('title',parent=style,fontSize=17,leading=22,spaceAfter=18)
def pdf(name,heading,paras):
    doc=SimpleDocTemplate(str(ROOT/name),pagesize=(595,842),leftMargin=48,rightMargin=48,topMargin=45,bottomMargin=48)
    story=[Paragraph(escape(heading),title)]
    for para in paras:
        story.extend([Paragraph(escape(para),style),Spacer(1,5)])
    def footer(canvas,doc):
        canvas.setFont('DejaVu',8);canvas.drawString(48,25,'Учебный пример проекта. Синтетические данные.');canvas.drawRightString(547,25,str(doc.page))
    doc.build(story,onFirstPage=footer,onLaterPages=footer)
pdf('study-notes.pdf','Алгоритмы и проверка программ',[short,second])
pdf('long-lecture.pdf','Как устроена обработка учебных материалов',paragraphs)
for path in ROOT.glob('*.txt'):
    text=path.read_text();print(path.name,len(text),len(text.encode()),'estimated tokens',(len(text.encode())+3)//4)
